/* Hindi (हिन्दी) demo content for the content collections, used once by the "i18n-hi-v1" migration
   (server/i18n/migrate.js). Keyed like server/pages-content.js: doctors and specialities by English name,
   packages by name, stories by patient name, FAQs by question, symptoms by label, chat replies by their
   first English keyword, articles by title, pages by slug.
   A value is only copied into an empty "<field>_hi" while the English field still matches the demo text it
   was translated from, so edits made in the admin are never overwritten and never paired with a stale
   translation. Placeholder copy for the fictional CareNova Hospitals, like the English. */

const { ARTICLES, PAGES } = require("./hi-content-pages");

/* ---------- small helpers for list-like fields ---------- */
const LANG_NAMES = { English: "अंग्रेज़ी", Hindi: "हिन्दी", Telugu: "तेलुगु", Tamil: "तमिल", Marathi: "मराठी", Malayalam: "मलयालम", Gujarati: "गुजराती", Urdu: "उर्दू", Punjabi: "पंजाबी", Bengali: "बांग्ला" };
const DAYS = { Mon: "सोम", Tue: "मंगल", Wed: "बुध", Thu: "गुरु", Fri: "शुक्र", Sat: "शनि", Sun: "रवि" };
/** "English, Hindi, Telugu" → "अंग्रेज़ी, हिन्दी, तेलुगु" */
const langHi = (en) => String(en).split(/\s*,\s*/).map((l) => LANG_NAMES[l] || l).join(", ");
/** "Mon–Sat · 10 AM – 2 PM" → "सोम–शनि · 10 AM – 2 PM" (times stay as written; the " · " format is kept) */
const opdHi = (en) => { const [days, ...rest] = String(en).split(" · "); return [days.replace(/\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b/g, (d) => DAYS[d]), ...rest].join(" · "); };

